lue) ** (1/n) - 1\n\n# Convert to percentage\ncagr_percent = cagr * 100\n\nprint(f'Beginning value (FY 1947): {beginning_value} million')\nprint(f'Ending value (FY 1950): {ending_value} million')\nprint(f'Years: {n}')\nprint(f'Ratio: {ending_value / beginning_value}')\nprint(f'CAGR (decimal): {cagr}')\nprint(f'CAGR (percent): {cagr_percent}')\nprint(f'Rounded to nearest thousandth: {round(cagr_percent, 3)}%')\n\""}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
